/**
 * Types shared with the web app. The schema types come straight from the API's OpenAPI spec
 * (src/api/v1.d.ts, generated by `npm run gen:api`), so a change in the API shows up here as a
 * type error. The app's own session endpoints return the same shapes.
 */
import type { components } from "./v1";

type S = components["schemas"];

export type Address = S["Address"];
export type Approval = S["Approval"];
export type Agent = S["Agent"];
export type Folder = "inbox" | "sent" | "drafts" | "archive" | "spam" | "trash";
export type ListFolder = Folder | "starred";

export type MessageSummary = S["MessageSummary"] & {
  /** Set when one of your agents wrote it. */
  sentByAgentId?: string | null;
};

export interface Attachment { id: string; filename: string; contentType: string; sizeBytes: number; available: boolean }

export interface Message extends MessageSummary {
  cc: Address[];
  bcc: Address[];
  replyTo: string | null;
  text: string;
  html: string | null;
  attachments: Attachment[];
}

export interface MessagePage { messages: MessageSummary[]; nextCursor: string | null }
export interface ThreadView { message: Message; thread: Message[] }

export interface MailboxOverview {
  id: string;
  address: string;
  displayName: string;
  usedBytes: number;
  quotaMb: number;
  kind?: "person" | "agent";
  folders: Partial<Record<Folder, { total: number; unread: number }>>;
}

export type Role = "owner" | "admin" | "member";

export interface Me {
  user: { id: string; email: string; name: string; emailVerified: boolean; twoFactor: boolean; platformAdmin: boolean };
  organization: { id: string; name: string; plan: string; isDemo: boolean; role: Role; timezone: string; country: string } | null;
}

export interface SendInput {
  mailboxId: string;
  to: string[];
  cc?: string[];
  subject: string;
  text: string;
  inReplyToId?: string;
}

export interface SendResult { messageId: string; status?: string; [k: string]: unknown }
